"""
This file introducing a function that can divide the list of structures to two, structures in one list  have contours and
structures in another list do not have contours.
The differenc lies in the structure label's name among other things.  The one that does not contain character '\xa0' has contours,
otherwise it does not has contour.
"""
from pyjab.jabdriver import JABDriver
from interops.libraries.mim.interactions.objects import mim_objects

def divide_structures_list(jab:JABDriver):
    '''
    Get the structures with/without contours from the list
    '''
    structures_with_contours = []
    structures_without_contours = []
    structure_list_filler = jab.find_element_by_uid(mim_objects.structure_list_filler_uid)
    if not structure_list_filler:
        raise Exception("Structure list not found")

    for structur_panel in structure_list_filler.children:
        structure_label = None
        if structur_panel.role == "panel":
            try:
                structure_label = structur_panel.children[0].children[0].children[3]#.find_element_by_xpath("/filler[@objectdepth=15 and @indexinparent=0]/filler[@indexinparent=0]/label[@indexinparent=3]")
                if structure_label:
                    if not '\xa0' in structure_label.name:
                        structures_with_contours.append(structure_label.name)
                    else:
                        structures_without_contours.append(structure_label.name.rstrip('\xa0'))
            except Exception:
                pass
    return structures_with_contours, structures_without_contours